mapper.update:
UPDATE push_deliveries SET status='SENDING',attempts=attempts+1,claim_token=#{claimToken},lease_until=#{leaseUntil,jdbcType=TIMESTAMP}
WHERE subscription_id=#{subscriptionId} AND dose_date=#{doseDate} AND dose_time=#{doseTime} AND reminder_kind=#{kind}
  AND attempts < 3 AND next_attempt_at <= #{now,jdbcType=TIMESTAMP}
  AND (status IN ('PENDING','RETRY') OR (status='SENDING' AND lease_until <= #{now,jdbcType=TIMESTAMP}))

UPDATE push_deliveries SET status=#{status},next_attempt_at=#{retryAt,jdbcType=TIMESTAMP},lease_until=NULL,claim_token=NULL,
  delivered_at=CASE WHEN #{status}='SENT' THEN #{now,jdbcType=TIMESTAMP} ELSE delivered_at END
WHERE subscription_id=#{subscriptionId} AND dose_date=#{doseDate} AND dose_time=#{doseTime} AND reminder_kind=#{kind}
  AND status='SENDING' AND claim_token=#{claimToken}
